import java.util.*;class DrainageStructureTest{public static void main(String[]a){List<RiverRibbon.Point> straight=new ArrayList<>();for(int x=40;x<=960;x+=8)straight.add(new RiverRibbon.Point(x,500,3.5,90));float[] flat=EnvironmentMap.filled(128*128,92);var network=new RiverRibbon.Network(List.of()).append(straight,3,83,flat,128,8,1,true);double maxDrift=0;for(var s:network.segments){maxDrift=Math.max(maxDrift,Math.abs(s.a().z()-500));if(Math.hypot(s.b().x()-s.a().x(),s.b().z()-s.a().z())>24)throw new AssertionError("Meander broke channel continuity");}var first=network.segments.get(0).a();var last=network.segments.get(network.segments.size()-1).b();if(Math.abs(first.z()-500)>.5||Math.abs(last.z()-500)>.5||Math.abs(first.x()-40)>.5||Math.abs(last.x()-960)>.5)throw new AssertionError("Meander moved river endpoints");if(maxDrift<12)throw new AssertionError("Straight drainage path left as a ruler line: drift="+maxDrift);if(maxDrift>260)throw new AssertionError("Meander drifted too far: "+maxDrift);var again=new RiverRibbon.Network(List.of()).append(straight,3,83,flat,128,8,1,true);for(int k=0;k<network.segments.size();k++)if(network.segments.get(k).a().z()!=again.segments.get(k).a().z())throw new AssertionError("Meander not repeatable");int n=128;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++){double valley=64+10*Math.sin(z/22.);h[z*n+x]=(float)(180-z*.85+Math.pow((x-valley)/8,2)*5);}var e=new EnvironmentMap(h);var routing=RiverCourse.route(h,e,n,1024,62,()->false);int start=18*n+(int)Math.round(64+10*Math.sin(18/22.)),cell=start,count=0;double error=0,minX=999,maxX=0;while(cell>=0&&count<128*128){int x=cell%n,z=cell/n;if(z>20&&z<110){error+=Math.abs(x-(64+10*Math.sin(z/22.)));minX=Math.min(minX,x);maxX=Math.max(maxX,x);}cell=routing.flow().parent()[cell];count++;}if(count>=n*n||maxX-minX<12||error/count>6)throw new AssertionError("Channel ignores winding valley: span="+(maxX-minX)+" error="+error/count);System.out.println("PASS: straight flat-ground course gains bounded, continuous, repeatable meanders (max drift "+Math.round(maxDrift)+" blocks); drainage follows a winding terrain valley with mean lateral error="+error/count);}}
